import{_ as o,c as t,o as i,ae as a}from"./chunks/framework.BrQRMotl.js";const p=JSON.parse('{"title":"Smooth Move Command","description":"","frontmatter":{},"headers":[],"relativePath":"manual/smooth_move.md","filePath":"manual/smooth_move.md"}'),n={name:"manual/smooth_move.md"};function s(l,e,r,c,d,m){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="smooth-move-command" tabindex="-1">Smooth Move Command <a class="header-anchor" href="#smooth-move-command" aria-label="Permalink to &quot;Smooth Move Command&quot;">​</a></h1><p><code>/smoothmove</code> is a powerful utility command that allows administrators to make players or entities move in a specified direction with smooth speed.</p><h2 id="command-syntax" tabindex="-1">Command Syntax <a class="header-anchor" href="#command-syntax" aria-label="Permalink to &quot;Command Syntax&quot;">​</a></h2><h3 id="_1-start-moving" tabindex="-1">1. Start Moving <a class="header-anchor" href="#_1-start-moving" aria-label="Permalink to &quot;1. Start Moving&quot;">​</a></h3><div class="language-mcfunction vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mcfunction</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/smoothmove &lt;target&gt; &lt;direction&gt; &lt;speed&gt; [duration]</span></span></code></pre></div><ul><li><strong>target</strong>: The entity selector to move (e.g., <code>@s</code>, <code>@p</code>, <code>@e[type=zombie]</code>).</li><li><strong>direction</strong>: <ul><li><code>north</code>, <code>south</code>, <code>east</code>, <code>west</code>: Cardinal directions.</li><li><code>x</code>, <code>-x</code>, <code>y</code>, <code>-y</code>, <code>z</code>, <code>-z</code>: Axis directions.</li><li><code>forward</code>: The direction the player is currently facing horizontally.</li><li><code>look</code>: The precise direction the player is looking (including vertical component).</li></ul></li><li><strong>speed</strong>: The distance moved per Tick (1 represents 20 blocks/second, assuming TPS=20).</li><li><strong>duration</strong> (Optional): The number of Ticks the movement lasts. If omitted, it will continue moving at this speed indefinitely.</li></ul><h3 id="_2-stop-moving" tabindex="-1">2. Stop Moving <a class="header-anchor" href="#_2-stop-moving" aria-label="Permalink to &quot;2. Stop Moving&quot;">​</a></h3><div class="language-mcfunction vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mcfunction</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/smoothmove stop &lt;target&gt;</span></span></code></pre></div><ul><li>Immediately forces the specified entity to stop smooth movement.</li></ul><h2 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core Features&quot;">​</a></h2><ol><li><strong>NoClip</strong>: <ul><li>During smooth movement, the entity enters a <code>noClip</code> state (similar to Spectator Mode), allowing it to pass through blocks without getting stuck or colliding.</li></ul></li><li><strong>Server Control</strong>: <ul><li>The movement trajectory is forcibly synchronized by the server, eliminating jitter (Rubberbanding) on the client side caused by network latency or collision detection.</li></ul></li><li><strong>Safety Protection</strong>: <ul><li>Fall damage for the entity is reset to 0 during movement, preventing death upon landing after long-distance travel.</li><li>After movement ends or stops, the entity resumes normal collision detection.</li></ul></li></ol>',11)])])}const u=o(n,[["render",s]]);export{p as __pageData,u as default};
